-- Generated by a one-off script from tools/class-columns.js - the
-- 75 vehicle-class columns below are copy-pasted from nowhere else,
-- they are generated from the exact same array tools/build-month-tables.js
-- uses for the offline import path, so the two paths cannot drift apart
-- on column names or order.
--
-- import_maker_month() is the ONLY way a single month+year of Maker x
-- Vehicle Class data can be replaced. It is deliberately narrow:
--
--   - p_month must be one of the 12 literal month codes below. The
--     table name is built with format(%I) only after that check, so
--     no caller-supplied text ever reaches a table/column identifier
--     unvalidated.
--   - p_year must be within the same 2000-2100 range the table's own
--     CHECK constraint enforces, checked here too so a bad year fails
--     before anything is touched rather than mid-statement.
--   - The whole call is one transaction: delete-then-insert either
--     both happen or neither does. A month is never left half-loaded.
--   - Only that one (month, year) pair is touched - DELETE is scoped
--     to "year" = p_year, matching the documented safe recovery path
--     in tools/schema.sql ("Deleting one year is only useful if you
--     are importing a single-year file"). Every other year, and every
--     other month table, is untouched.
--   - Granted to service_role only. anon and authenticated - the
--     roles the dashboard's publishable key can ever authenticate
--     as - are explicitly revoked, so the publishable key already
--     shipped in script.js cannot call this even by hand-crafting a
--     REST request to /rest/v1/rpc/import_maker_month.

CREATE OR REPLACE FUNCTION public.import_maker_month(
    p_month text,
    p_year integer,
    p_rows jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_table      text;
    v_deleted    integer;
    v_inserted   integer;
    v_units      bigint;
    v_mismatches jsonb;
BEGIN
    IF p_month NOT IN ('Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec') THEN
        RAISE EXCEPTION 'import_maker_month: unknown month %', p_month
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    IF p_year IS NULL OR p_year < 2000 OR p_year > 2100 THEN
        RAISE EXCEPTION 'import_maker_month: year % out of range', p_year
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array'
            OR jsonb_array_length(p_rows) = 0 THEN
        RAISE EXCEPTION 'import_maker_month: rows must be a non-empty array'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    v_table := format('Maker_Class_Wise_%s', p_month);

    EXECUTE format('DELETE FROM %I WHERE "year" = $1', v_table)
        USING p_year;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;

    EXECUTE format(
        'INSERT INTO %I ("year", "Maker", "Three Wheeler (Goods)", "Three Wheeler (Passenger)", "e-Rickshaw with Cart (G)", "e-Rickshaw(P)", "Tractor-Trolley(Commercial)", "Trailer (Agricultural)", "Harvester", "Goods Carrier", "M-Cycle/Scooter", "Trailer (Commercial)", "Construction Equipment Vehicle", "Crane Mounted Vehicle", "Agricultural Tractor", "Construction Equipment Vehicle (Commercial)", "Earth Moving Equipment", "Excavator (Commercial)", "Excavator (NT)", "Fork Lift", "Road Roller", "Tractor (Commercial)", "Motorised Cycle (CC  25cc)", "Bus", "Semi-Trailer (Commercial)", "Motor Car", "Vehicle Fitted With Rig", "Moped", "Armoured/Specialised Vehicle", "Ambulance", "Animal Ambulance", "Articulated Vehicle", "Auxiliary Trailer", "Camper Van / Trailer", "Camper Van / Trailer (Private Use)", "Dumper", "Educational Institution Bus", "Fire Fighting Vehicle", "Fire Tenders", "Hearses", "Maxi Cab", "Mobile Canteen", "Mobile Clinic", "Mobile Workshop", "Omni Bus", "Private Service Vehicle", "Private Service Vehicle (Individual Use)", "Puller Tractor", "Recovery Vehicle", "School Bus", "Snorked Ladders", "Tow Truck", "Tower Wagon", "Tree Trimming Vehicle", "Vehicle Fitted With Compressor", "Vehicle Fitted With Generator", "X-Ray Van", "Adapted Vehicle", "M-Cycle/Scooter-With Side Car", "Motor Cycle/Scooter-Used For Hire", "Three Wheeler (Personal)", "Motor Cab", "Motor Cycle/Scooter-SideCar(T)", "Quadricycle (Commercial)", "Quadricycle (Private)", "Luxury Cab", "Breakdown Van", "Cash Van", "Library Van", "Omni Bus (Private Use)", "Vintage Motor Vehicle", "Trailer For Personal Use", "Motor Caravan", "Power Tiller", "Modular Hydraulic Trailer", "Bulldozer", "Motor Cycle/Scooter-With Trailer", "Total")
         SELECT $2, t."Maker", coalesce(t."Three Wheeler (Goods)", 0), coalesce(t."Three Wheeler (Passenger)", 0), coalesce(t."e-Rickshaw with Cart (G)", 0), coalesce(t."e-Rickshaw(P)", 0), coalesce(t."Tractor-Trolley(Commercial)", 0), coalesce(t."Trailer (Agricultural)", 0), coalesce(t."Harvester", 0), coalesce(t."Goods Carrier", 0), coalesce(t."M-Cycle/Scooter", 0), coalesce(t."Trailer (Commercial)", 0), coalesce(t."Construction Equipment Vehicle", 0), coalesce(t."Crane Mounted Vehicle", 0), coalesce(t."Agricultural Tractor", 0), coalesce(t."Construction Equipment Vehicle (Commercial)", 0), coalesce(t."Earth Moving Equipment", 0), coalesce(t."Excavator (Commercial)", 0), coalesce(t."Excavator (NT)", 0), coalesce(t."Fork Lift", 0), coalesce(t."Road Roller", 0), coalesce(t."Tractor (Commercial)", 0), coalesce(t."Motorised Cycle (CC  25cc)", 0), coalesce(t."Bus", 0), coalesce(t."Semi-Trailer (Commercial)", 0), coalesce(t."Motor Car", 0), coalesce(t."Vehicle Fitted With Rig", 0), coalesce(t."Moped", 0), coalesce(t."Armoured/Specialised Vehicle", 0), coalesce(t."Ambulance", 0), coalesce(t."Animal Ambulance", 0), coalesce(t."Articulated Vehicle", 0), coalesce(t."Auxiliary Trailer", 0), coalesce(t."Camper Van / Trailer", 0), coalesce(t."Camper Van / Trailer (Private Use)", 0), coalesce(t."Dumper", 0), coalesce(t."Educational Institution Bus", 0), coalesce(t."Fire Fighting Vehicle", 0), coalesce(t."Fire Tenders", 0), coalesce(t."Hearses", 0), coalesce(t."Maxi Cab", 0), coalesce(t."Mobile Canteen", 0), coalesce(t."Mobile Clinic", 0), coalesce(t."Mobile Workshop", 0), coalesce(t."Omni Bus", 0), coalesce(t."Private Service Vehicle", 0), coalesce(t."Private Service Vehicle (Individual Use)", 0), coalesce(t."Puller Tractor", 0), coalesce(t."Recovery Vehicle", 0), coalesce(t."School Bus", 0), coalesce(t."Snorked Ladders", 0), coalesce(t."Tow Truck", 0), coalesce(t."Tower Wagon", 0), coalesce(t."Tree Trimming Vehicle", 0), coalesce(t."Vehicle Fitted With Compressor", 0), coalesce(t."Vehicle Fitted With Generator", 0), coalesce(t."X-Ray Van", 0), coalesce(t."Adapted Vehicle", 0), coalesce(t."M-Cycle/Scooter-With Side Car", 0), coalesce(t."Motor Cycle/Scooter-Used For Hire", 0), coalesce(t."Three Wheeler (Personal)", 0), coalesce(t."Motor Cab", 0), coalesce(t."Motor Cycle/Scooter-SideCar(T)", 0), coalesce(t."Quadricycle (Commercial)", 0), coalesce(t."Quadricycle (Private)", 0), coalesce(t."Luxury Cab", 0), coalesce(t."Breakdown Van", 0), coalesce(t."Cash Van", 0), coalesce(t."Library Van", 0), coalesce(t."Omni Bus (Private Use)", 0), coalesce(t."Vintage Motor Vehicle", 0), coalesce(t."Trailer For Personal Use", 0), coalesce(t."Motor Caravan", 0), coalesce(t."Power Tiller", 0), coalesce(t."Modular Hydraulic Trailer", 0), coalesce(t."Bulldozer", 0), coalesce(t."Motor Cycle/Scooter-With Trailer", 0), t."Total"
         FROM jsonb_to_recordset($1) AS t(
            "Maker" text,
            "Three Wheeler (Goods)" integer,
            "Three Wheeler (Passenger)" integer,
            "e-Rickshaw with Cart (G)" integer,
            "e-Rickshaw(P)" integer,
            "Tractor-Trolley(Commercial)" integer,
            "Trailer (Agricultural)" integer,
            "Harvester" integer,
            "Goods Carrier" integer,
            "M-Cycle/Scooter" integer,
            "Trailer (Commercial)" integer,
            "Construction Equipment Vehicle" integer,
            "Crane Mounted Vehicle" integer,
            "Agricultural Tractor" integer,
            "Construction Equipment Vehicle (Commercial)" integer,
            "Earth Moving Equipment" integer,
            "Excavator (Commercial)" integer,
            "Excavator (NT)" integer,
            "Fork Lift" integer,
            "Road Roller" integer,
            "Tractor (Commercial)" integer,
            "Motorised Cycle (CC  25cc)" integer,
            "Bus" integer,
            "Semi-Trailer (Commercial)" integer,
            "Motor Car" integer,
            "Vehicle Fitted With Rig" integer,
            "Moped" integer,
            "Armoured/Specialised Vehicle" integer,
            "Ambulance" integer,
            "Animal Ambulance" integer,
            "Articulated Vehicle" integer,
            "Auxiliary Trailer" integer,
            "Camper Van / Trailer" integer,
            "Camper Van / Trailer (Private Use)" integer,
            "Dumper" integer,
            "Educational Institution Bus" integer,
            "Fire Fighting Vehicle" integer,
            "Fire Tenders" integer,
            "Hearses" integer,
            "Maxi Cab" integer,
            "Mobile Canteen" integer,
            "Mobile Clinic" integer,
            "Mobile Workshop" integer,
            "Omni Bus" integer,
            "Private Service Vehicle" integer,
            "Private Service Vehicle (Individual Use)" integer,
            "Puller Tractor" integer,
            "Recovery Vehicle" integer,
            "School Bus" integer,
            "Snorked Ladders" integer,
            "Tow Truck" integer,
            "Tower Wagon" integer,
            "Tree Trimming Vehicle" integer,
            "Vehicle Fitted With Compressor" integer,
            "Vehicle Fitted With Generator" integer,
            "X-Ray Van" integer,
            "Adapted Vehicle" integer,
            "M-Cycle/Scooter-With Side Car" integer,
            "Motor Cycle/Scooter-Used For Hire" integer,
            "Three Wheeler (Personal)" integer,
            "Motor Cab" integer,
            "Motor Cycle/Scooter-SideCar(T)" integer,
            "Quadricycle (Commercial)" integer,
            "Quadricycle (Private)" integer,
            "Luxury Cab" integer,
            "Breakdown Van" integer,
            "Cash Van" integer,
            "Library Van" integer,
            "Omni Bus (Private Use)" integer,
            "Vintage Motor Vehicle" integer,
            "Trailer For Personal Use" integer,
            "Motor Caravan" integer,
            "Power Tiller" integer,
            "Modular Hydraulic Trailer" integer,
            "Bulldozer" integer,
            "Motor Cycle/Scooter-With Trailer" integer,
            "Total" integer
         )',
        v_table
    ) USING p_rows, p_year;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;

    EXECUTE format(
        'SELECT coalesce(sum("Total"), 0) FROM %I WHERE "year" = $1',
        v_table
    ) INTO v_units USING p_year;

    /*
     * A mismatch here is reported, not raised - the CLI path
     * (build-month-tables.js) has always loaded a row even when its
     * class columns do not sum to its own Total, flagging it as a
     * warning for a human to see rather than refusing the file. This
     * keeps that same behaviour: the caller gets the list back and
     * decides, the transaction still commits.
     */
    EXECUTE format(
        'SELECT coalesce(jsonb_agg(jsonb_build_object(
                ''maker'', "Maker", ''total'', "Total", ''summed'', summed
            )), ''[]''::jsonb)
         FROM (
             SELECT t."Maker", t."Total", (coalesce(t."Three Wheeler (Goods)", 0) + coalesce(t."Three Wheeler (Passenger)", 0) + coalesce(t."e-Rickshaw with Cart (G)", 0) + coalesce(t."e-Rickshaw(P)", 0) + coalesce(t."Tractor-Trolley(Commercial)", 0) + coalesce(t."Trailer (Agricultural)", 0) + coalesce(t."Harvester", 0) + coalesce(t."Goods Carrier", 0) + coalesce(t."M-Cycle/Scooter", 0) + coalesce(t."Trailer (Commercial)", 0) + coalesce(t."Construction Equipment Vehicle", 0) + coalesce(t."Crane Mounted Vehicle", 0) + coalesce(t."Agricultural Tractor", 0) + coalesce(t."Construction Equipment Vehicle (Commercial)", 0) + coalesce(t."Earth Moving Equipment", 0) + coalesce(t."Excavator (Commercial)", 0) + coalesce(t."Excavator (NT)", 0) + coalesce(t."Fork Lift", 0) + coalesce(t."Road Roller", 0) + coalesce(t."Tractor (Commercial)", 0) + coalesce(t."Motorised Cycle (CC  25cc)", 0) + coalesce(t."Bus", 0) + coalesce(t."Semi-Trailer (Commercial)", 0) + coalesce(t."Motor Car", 0) + coalesce(t."Vehicle Fitted With Rig", 0) + coalesce(t."Moped", 0) + coalesce(t."Armoured/Specialised Vehicle", 0) + coalesce(t."Ambulance", 0) + coalesce(t."Animal Ambulance", 0) + coalesce(t."Articulated Vehicle", 0) + coalesce(t."Auxiliary Trailer", 0) + coalesce(t."Camper Van / Trailer", 0) + coalesce(t."Camper Van / Trailer (Private Use)", 0) + coalesce(t."Dumper", 0) + coalesce(t."Educational Institution Bus", 0) + coalesce(t."Fire Fighting Vehicle", 0) + coalesce(t."Fire Tenders", 0) + coalesce(t."Hearses", 0) + coalesce(t."Maxi Cab", 0) + coalesce(t."Mobile Canteen", 0) + coalesce(t."Mobile Clinic", 0) + coalesce(t."Mobile Workshop", 0) + coalesce(t."Omni Bus", 0) + coalesce(t."Private Service Vehicle", 0) + coalesce(t."Private Service Vehicle (Individual Use)", 0) + coalesce(t."Puller Tractor", 0) + coalesce(t."Recovery Vehicle", 0) + coalesce(t."School Bus", 0) + coalesce(t."Snorked Ladders", 0) + coalesce(t."Tow Truck", 0) + coalesce(t."Tower Wagon", 0) + coalesce(t."Tree Trimming Vehicle", 0) + coalesce(t."Vehicle Fitted With Compressor", 0) + coalesce(t."Vehicle Fitted With Generator", 0) + coalesce(t."X-Ray Van", 0) + coalesce(t."Adapted Vehicle", 0) + coalesce(t."M-Cycle/Scooter-With Side Car", 0) + coalesce(t."Motor Cycle/Scooter-Used For Hire", 0) + coalesce(t."Three Wheeler (Personal)", 0) + coalesce(t."Motor Cab", 0) + coalesce(t."Motor Cycle/Scooter-SideCar(T)", 0) + coalesce(t."Quadricycle (Commercial)", 0) + coalesce(t."Quadricycle (Private)", 0) + coalesce(t."Luxury Cab", 0) + coalesce(t."Breakdown Van", 0) + coalesce(t."Cash Van", 0) + coalesce(t."Library Van", 0) + coalesce(t."Omni Bus (Private Use)", 0) + coalesce(t."Vintage Motor Vehicle", 0) + coalesce(t."Trailer For Personal Use", 0) + coalesce(t."Motor Caravan", 0) + coalesce(t."Power Tiller", 0) + coalesce(t."Modular Hydraulic Trailer", 0) + coalesce(t."Bulldozer", 0) + coalesce(t."Motor Cycle/Scooter-With Trailer", 0)) AS summed
             FROM %I AS t WHERE t."year" = $1
         ) s
         WHERE s."Total" IS DISTINCT FROM s.summed',
        v_table
    ) INTO v_mismatches USING p_year;

    RETURN jsonb_build_object(
        'table', v_table,
        'year', p_year,
        'deleted', v_deleted,
        'inserted', v_inserted,
        'units', v_units,
        'mismatches', v_mismatches
    );
END;
$$;

REVOKE ALL ON FUNCTION public.import_maker_month(text, integer, jsonb)
    FROM PUBLIC;

/*
 * PUBLIC alone is not enough on Supabase: new functions in the
 * public schema get EXECUTE granted directly to anon and
 * authenticated by ALTER DEFAULT PRIVILEGES set up when the project
 * was provisioned - a separate, specific grant, not something
 * inherited through PUBLIC, so revoking from PUBLIC does not touch
 * it. Both are revoked explicitly here for exactly that reason -
 * confirmed by testing directly against the live project, where the
 * PUBLIC-only revoke below left anon able to call this function.
 */
REVOKE ALL ON FUNCTION public.import_maker_month(text, integer, jsonb)
    FROM anon, authenticated;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
        GRANT EXECUTE ON FUNCTION public.import_maker_month(text, integer, jsonb)
            TO service_role;
    END IF;
END;
$$;
